fn param_completions<'a>(
    ctx: &mut CompletionContext<'a>,
    callee: &LinkedNode<'a>,
    set: bool,
    args: ast::Args<'a>,
    args_linked: &LinkedNode<'a>,
) {
    let Some(value) = analyze_expr_with_fallback(ctx.world, callee) else { return };
