   fn test_rect_skips_filled_param() {
       let res = test("#rect(fill: red, )", -2);
       // fill 已填 → 不应再出现
       res.must_exclude(["fill"]);
       // 其它可设置参数应出现
       res.must_include(["width", "height"]);
